#!/usr/bin/env python3
"""Publish the AZMEDNSK case collection, homepage entry and sitemap together."""
import base64
from collections import Counter
from datetime import datetime, timezone
import fcntl
from html.parser import HTMLParser
import io
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import tarfile
import tempfile
from urllib.parse import urljoin, urlsplit
import xml.etree.ElementTree as ET


ARCHIVE = ''
ORIGIN = "https://azmednsk.ru"
SITEMAP_NS = "{http://www.sitemaps.org/schemas/sitemap/0.9}"
PAIR = (
    '<a class="az-home-half" href="/chto-my-lechim/" aria-label="Что мы лечим">Что мы лечим</a>'
    '<a class="az-home-half az-home-faq-link" href="/otvety-na-voprosy/" '
    'aria-label="Ответы на вопросы">Ответы на вопросы</a>'
)
LINK = '<a class="az-home-cases" href="/cases/">Наши кейсы<span aria-hidden="true">↗</span></a>'
STYLE = """<style id="az-home-cases-style">
.azh-home .nav>a.az-home-cases {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-width: 0;
  padding: 8px 16px;
  border: 1px solid #9cc6dc;
  background: #f0f7fc;
  color: #166ca2;
  font-weight: 600;
}
.azh-home .nav>a.az-home-cases:hover,
.azh-home .nav>a.az-home-cases:focus-visible {
  background: #eaf5fc;
  border-color: #2080c4;
}
</style>"""


class PageLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.refs = []
        self.h1 = 0

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "h1":
            self.h1 += 1
        self.refs.extend(attrs[k] for k in ("href", "src") if attrs.get(k))


def bundle(encoded):
    files = {}
    pages = {}
    compressed = base64.b64decode(encoded, validate=True)
    with tarfile.open(fileobj=io.BytesIO(compressed), mode="r:gz") as archive:
        for member in archive:
            name = PurePosixPath(member.name)
            if not name.parts or name.parts[0] != "cases" or ".." in name.parts:
                raise ValueError("Недопустимый путь в архиве")
            if member.isdir():
                continue
            rel = name.relative_to("cases").as_posix()
            is_page = re.fullmatch(r"(?:[a-z0-9]+(?:-[a-z0-9]+)*/)?index\.html", rel)
            is_asset = re.fullmatch(r"assets/(?:[A-Za-z0-9_-]+/)*[A-Za-z0-9._-]+\.(?:webp|css|js)", rel)
            if not member.isfile() or rel in files or not (is_page or is_asset):
                raise ValueError("Неожиданный файл в архиве: " + rel)
            data = archive.extractfile(member).read()
            if not data:
                raise ValueError("Пустой файл в архиве: " + rel)
            if rel.endswith(".webp") and not (data.startswith(b"RIFF") and data[8:12] == b"WEBP"):
                raise ValueError("Неверный формат WebP: " + rel)
            files[rel] = data
            if is_page:
                pages["/cases/" + rel[:-len("index.html")]] = rel
    if len(pages) != 12 or "/cases/" not in pages:
        raise ValueError("В пакете ожидаются каталог и одиннадцать историй")
    for url, rel in pages.items():
        parser = PageLinks()
        parser.feed(files[rel].decode("utf-8"))
        parser.close()
        if parser.h1 != 1:
            raise ValueError("Проверьте основной заголовок: " + rel)
        targets = set()
        for ref in parser.refs:
            target = urlsplit(urljoin(ORIGIN + url, ref))
            if target.netloc != "azmednsk.ru" or not target.path.startswith("/cases/"):
                continue
            path = target.path
            if path not in pages and path[len("/cases/"):] not in files:
                raise ValueError("Отсутствует файл для ссылки " + ref + " на " + url)
            targets.add(path)
        if url == "/cases/" and not set(pages).difference({url}).issubset(targets):
            raise ValueError("В каталоге отсутствуют ссылки на истории")
    return files, pages


def homepage(original):
    page = original.decode("utf-8")
    if page.count(PAIR + LINK + "</nav>") == 1 and page.count(STYLE) == 1:
        return original
    if (page.count(PAIR + "</nav>") != 1 or page.count("</head>") != 1
            or "az-home-cases" in page):
        raise ValueError("Главная изменилась. Проверьте место вставки плашки.")
    page = page.replace(PAIR + "</nav>", PAIR + LINK + "</nav>")
    return page.replace("</head>", STYLE + "</head>").encode("utf-8")


def sitemap(original, pages):
    tree = ET.fromstring(original)
    if tree.tag != SITEMAP_NS + "urlset" or original.count(b"</urlset>") != 1:
        raise ValueError("Неизвестный формат карты сайта")
    desired = {ORIGIN + url for url in pages}
    existing = Counter(loc.text or "" for loc in tree.findall(
        SITEMAP_NS + "url/" + SITEMAP_NS + "loc"
    ))
    if any(existing[url] > 1 for url in desired):
        # Remove only duplicate entries for this collection, retaining every other byte.
        seen = set()

        def remove_duplicate(match):
            node = ET.fromstring(match.group())
            url = node.findtext("loc")
            if url in desired:
                if url in seen:
                    return b""
                seen.add(url)
            return match.group()

        original = re.sub(rb"<url\s*>.*?</url\s*>", remove_duplicate, original, flags=re.S)
    missing = sorted(url for url in desired if not existing[url])
    entries = b"".join(b"<url><loc>" + url.encode("ascii") + b"</loc></url>\n" for url in missing)
    result = original.replace(b"</urlset>", entries + b"</urlset>")
    counts = Counter(loc.text for loc in ET.fromstring(result).findall(
        SITEMAP_NS + "url/" + SITEMAP_NS + "loc"
    ))
    if any(counts[url] != 1 for url in desired):
        raise ValueError("Не удалось добавить адреса в карту сайта")
    return result


def write_replacement(target, previous, new):
    if previous == new:
        return
    if target.is_symlink() or target.read_bytes() != previous:
        raise RuntimeError("Файл изменился во время установки: " + str(target))
    meta = target.stat()
    with tempfile.NamedTemporaryFile(dir=target.parent, prefix=".az-cases-write-", delete=False) as out:
        tmp = Path(out.name)
        try:
            out.write(new)
            out.flush()
            if os.geteuid() == 0:
                os.fchown(out.fileno(), meta.st_uid, meta.st_gid)
            os.fchmod(out.fileno(), stat.S_IMODE(meta.st_mode))
            os.fsync(out.fileno())
            if target.is_symlink() or target.read_bytes() != previous:
                raise RuntimeError("Файл изменился во время установки: " + str(target))
            os.replace(tmp, target)
        finally:
            tmp.unlink(missing_ok=True)


def matching_directory(path, files):
    if path.is_symlink() or not path.is_dir():
        return False
    required_dirs = {p.as_posix() for name in files for p in PurePosixPath(name).parents}
    found = set()
    for child in path.rglob("*"):
        rel = child.relative_to(path).as_posix()
        if child.is_symlink():
            return False
        if child.is_dir() and rel in required_dirs:
            continue
        if not child.is_file() or rel not in files or child.read_bytes() != files[rel]:
            return False
        found.add(rel)
    return found == set(files)


def tree_state(path, files):
    if path.is_symlink():
        raise ValueError("Путь /cases/ является ссылкой")
    if not path.exists():
        return "missing"
    if path.is_dir() and not any(path.iterdir()):
        return "empty"
    if matching_directory(path, files):
        return "ready"
    raise ValueError("Существующий /cases/ отличается от пакета. Установка остановлена.")


def stage_tree(path, files):
    for rel, data in files.items():
        item = path / rel
        item.parent.mkdir(parents=True, exist_ok=True)
        item.write_bytes(data)
        item.chmod(0o644)
    for folder in [path, *(p for p in path.rglob("*") if p.is_dir())]:
        folder.chmod(0o755)


def install(root, backups, encoded):
    files, pages = bundle(encoded)
    backups.mkdir(parents=True, exist_ok=True)
    dfd = os.open(backups, os.O_RDONLY | os.O_DIRECTORY)
    try:
        fcntl.flock(dfd, fcntl.LOCK_EX)
        publish(root, backups, files, pages)
    finally:
        os.close(dfd)


def publish(root, backups, files, pages):
    cases = root / "cases"
    home, site_map = root / "index.html", root / "sitemap.xml"
    if any(p.is_symlink() or not p.is_file() for p in (home, site_map)):
        raise ValueError("Проверьте главную страницу и карту сайта")
    originals = {p: p.read_bytes() for p in (home, site_map)}
    new = {home: homepage(originals[home]), site_map: sitemap(originals[site_map], pages)}
    initial = tree_state(cases, files)
    if initial == "ready" and new == originals:
        print("CASES=ALREADY_INSTALLED; PAGES=12")
        return
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    backup = backups / ("cases-" + stamp)
    backup.mkdir(mode=0o700)
    for path in originals:
        shutil.copy2(path, backup / path.name)
        if (backup / path.name).read_bytes() != originals[path]:
            raise RuntimeError("Исходный файл изменился при резервном копировании")
    print("BACKUP=" + str(backup), flush=True)
    published = False
    updated = []
    with tempfile.TemporaryDirectory(dir=root, prefix=".az-cases-stage-") as temp:
        staged = Path(temp) / "cases"
        try:
            if initial != "ready":
                stage_tree(staged, files)
                if not matching_directory(staged, files) or tree_state(cases, files) != initial:
                    raise RuntimeError("Дерево /cases/ изменилось при подготовке")
                # A pre-existing empty directory is renamed into private staging for rollback.
                if initial == "empty":
                    cases.rename(Path(temp) / "original-empty")
                staged.rename(cases)
                published = True
            for path in (site_map, home):
                if new[path] != originals[path]:
                    write_replacement(path, originals[path], new[path])
                    updated.append(path)
            if not matching_directory(cases, files) or any(p.read_bytes() != new[p] for p in new):
                raise RuntimeError("Проверка опубликованных файлов не пройдена")
        except BaseException:
            for path in reversed(updated):
                write_replacement(path, new[path], originals[path])
            if published and matching_directory(cases, files):
                cases.rename(staged)
            previous = Path(temp) / "original-empty"
            if previous.exists() and not cases.exists():
                previous.rename(cases)
            raise
    print("CASES=PASS; STORIES=11; HOME_TILE=PASS; SITEMAP=PASS")
    print("URL=" + ORIGIN + "/cases/")


if __name__ == "__main__":
    install(Path("/var/www/azmednsk-preview"), Path("/var/backups/azmednsk"), ARCHIVE)
